// ГЧХ АЖЛЫН МЭДЭЭ тайлангийн ЗАГВАРЫН СПЕК.
//
// Энэ файл нь `public/reports/ГЧХ-2 АЖЛЫН МЭДЭЭ.xlsx`-ээс АВТОМАТААР задлан
// гаргасан бүтэц (багана өргөн, 3 давхар гарчиг, merge, стиль, хэвлэлтийн
// тохиргоо). Excel-ийг ЗАГВАР ФАЙЛГҮЙГЭЭР, шинээр угсрахад хэрэглэнэ —
// runtime-д ямар ч .xlsx уншихгүй.
//
// ӨНГӨ: загвар нь Office 2024 theme (accent1=156082) хэрэглэдэг ба exceljs-ийн
// анхдагч theme нь ХУУЧИН палитр (accent1=4F81BD). Иймд theme индекс биш,
// tint-ийг тооцоолсон ТОДОРХОЙ ARGB утгыг хадгалав — ямар ч theme дээр өнгө
// ижил гарна.

export type BorderStyle = "thin" | "medium" | "thick" | "double" | null;

export interface CellStyleSpec {
  font: { bold?: boolean; size?: number; color?: string };
  fill?: string;
  align?: { horizontal?: string; vertical?: string; wrapText?: boolean; textRotation?: number };
  numFmt?: string;
  /** [top, left, bottom, right] */
  border?: BorderStyle[];
}

/** Мөрийн төрөл бүрийн 54 баганын стиль. */
export interface RowStyles {
  /** Гарчгийн 1-3 мөр */
  h1: CellStyleSpec[]; h2: CellStyleSpec[]; h3: CellStyleSpec[];
  /** Ажлын (өгөгдлийн) мөр */
  data: CellStyleSpec[];
  /** Дэд ангиллын нийт мөр */
  sub: CellStyleSpec[];
  /** Ерөнхий ангиллын нийт мөр */
  cat: CellStyleSpec[];
  /** Бүх дүнгийн мөр */
  grand: CellStyleSpec[];
}

